using Microsoft.EntityFrameworkCore;
using System.Text;
namespace Society.Api;
public static partial class CommunicationEndpoints {
 static void MapOperations(RouteGroupBuilder t){
 t.MapGet("/accounts",async(Guid tenant,AppDb db,Access a)=>{await a.Member(tenant);var all=await a.Can(tenant,"communications.accounts");var units=a.Visible(tenant,"communications.send").Select(u=>u.Id);return await db.Set<CommunicationAccount>().Where(ac=>ac.TenantId==tenant&&(all||ac.UnitId==null&&units.Any()||ac.UnitId!=null&&units.Contains(ac.UnitId.Value))).OrderBy(ac=>ac.Name).Select(ac=>new{ac.Id,ac.UnitId,ac.Name,ac.Channel,ac.Provider,ac.Sender,ac.ProviderReference,ac.Enabled,ac.Verified,ac.InboundEnabled,ac.Health,ac.PerMinute,ac.CheckedAt,hasSecrets=ac.ProtectedSecrets!=""}).ToListAsync();});
 t.MapPost("/accounts",async(Guid tenant,AccountWrite r,AppDb db,Access a,CommunicationProviders providers)=>{await a.Require(tenant,"communications.accounts",r.UnitId);ValidateAccount(r,providers);var account=new CommunicationAccount{TenantId=tenant};ApplyAccount(account,r,providers);db.Add(account);a.Audit(tenant,"communication.account.created",account.Id,new{r.Channel,r.Provider});await db.SaveChangesAsync();return Results.Ok(new{account.Id});});
 t.MapPut("/accounts/{id:guid}",async(Guid tenant,Guid id,AccountWrite r,AppDb db,Access a,CommunicationProviders providers)=>{var account=await db.Set<CommunicationAccount>().SingleOrDefaultAsync(ac=>ac.TenantId==tenant&&ac.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"communications.accounts",account.UnitId);if(r.UnitId!=account.UnitId)throw new DomainException("Account scope is immutable");ValidateAccount(r,providers);ApplyAccount(account,r,providers);a.Audit(tenant,"communication.account.updated",id);await db.SaveChangesAsync();return Results.NoContent();});
 t.MapPost("/accounts/{id:guid}/verify",async(Guid tenant,Guid id,AppDb db,Access a,CommunicationProviders providers)=>{var account=await db.Set<CommunicationAccount>().SingleOrDefaultAsync(ac=>ac.TenantId==tenant&&ac.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"communications.accounts",account.UnitId);try{account.Verified=await providers.Verify(account,providers.Secrets(account),CancellationToken.None);account.Health=account.Verified?(account.Provider=="Test"?"Verified test adapter; no external delivery":"Verified provider sender"):"Sender verification failed";}catch{account.Verified=false;account.Health="Provider verification unavailable; check server-side configuration";}account.CheckedAt=DateTimeOffset.UtcNow;a.Audit(tenant,"communication.account.verified",id,new{account.Verified});await db.SaveChangesAsync();return Results.Ok(new{account.Verified,account.Health});});
 t.MapPost("/accounts/{id:guid}/templates/sync",async(Guid tenant,Guid id,AppDb db,Access a,CommunicationProviders providers)=>{var account=await db.Set<CommunicationAccount>().SingleOrDefaultAsync(ac=>ac.TenantId==tenant&&ac.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"communications.accounts",account.UnitId);var count=await MetaTemplates.Sync(db,account,providers,CancellationToken.None);a.Audit(tenant,"communication.templates.synchronized",id,new{count});await db.SaveChangesAsync();return Results.Ok(new{count});});
 t.MapGet("/delivery",async(Guid tenant,Guid? campaign,Guid? workspace,string? status,int? page,AppDb db,Access a)=>{await a.Member(tenant);var units=a.InWorkspace(a.Visible(tenant,"communications.send"),tenant,workspace).Select(u=>u.Id);var all=workspace==null&&await a.Can(tenant,"communications.send");var q=db.Outbox.Where(o=>o.TenantId==tenant&&(all||o.UnitId!=null&&units.Contains(o.UnitId.Value)));if(campaign!=null)q=q.Where(o=>o.CampaignId==campaign);if(status!=null)q=q.Where(o=>o.Status==status);return Results.Ok(new{total=await q.CountAsync(),items=await q.OrderByDescending(o=>o.CreatedAt).Skip(Math.Clamp((page??1)-1,0,100000)*50).Take(50).Select(o=>new{o.Id,o.Channel,o.Status,o.Subject,o.CreatedAt,o.NextAttemptAt,o.Attempts,o.Error,o.ProviderId,o.SentAt,o.DeliveredAt,o.ReadAt,o.CampaignId}).ToListAsync()});});
 t.MapPost("/delivery/{id:guid}/retry",async(Guid tenant,Guid id,ReportWrite r,AppDb db,Access a)=>{await using var tx=await db.Database.BeginTransactionAsync();var list=await db.Outbox.FromSqlInterpolated($"SELECT * FROM \"Outbox\" WHERE \"Id\"={id} AND \"TenantId\"={tenant} FOR UPDATE").ToListAsync();var job=list.SingleOrDefault()??throw new AccessDeniedException();await a.Require(tenant,"communications.send",job.UnitId);if(job.Status is not("DeadLetter" or "Failed" or "Unavailable"))throw new DomainException("Only definite failures can be retried; uncertain outcomes require provider reconciliation");if(string.IsNullOrWhiteSpace(r.Reason))throw new DomainException("Document the retry reason");job.Status="Queued";job.Attempts=0;job.NextAttemptAt=DateTimeOffset.UtcNow;job.SentAt=null;job.Error=null;a.Audit(tenant,"communication.delivery.retried",id,new{r.Reason});await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
 t.MapGet("/analytics",async(Guid tenant,Guid? workspace,Guid? campaign,DateTimeOffset? from,DateTimeOffset? to,AppDb db,Access a)=>{await a.Member(tenant);var all=await a.Can(tenant,"communications.analytics");var units=a.InWorkspace(a.Visible(tenant,"communications.analytics"),tenant,workspace).Select(u=>u.Id);if(!all&&!await units.AnyAsync())throw new AccessDeniedException();var start=from??DateTimeOffset.UtcNow.AddDays(-30);var end=to??DateTimeOffset.UtcNow;if(end<=start||end-start>TimeSpan.FromDays(366))throw new DomainException("Select a date range up to one year");var q=db.Outbox.Where(o=>o.TenantId==tenant&&o.CreatedAt>=start&&o.CreatedAt<end);if(!all||workspace!=null)q=q.Where(o=>o.UnitId!=null&&units.Contains(o.UnitId.Value));if(campaign!=null)q=q.Where(o=>o.CampaignId==campaign);var ids=q.Select(o=>o.Id);var attempts=db.Set<DeliveryAttempt>().Where(at=>at.TenantId==tenant&&ids.Contains(at.OutboxId));return Results.Ok(new{from=start,to=end,queued=await q.CountAsync(o=>o.Status=="Queued"||o.Status=="Retry"),attempted=await attempts.CountAsync(),accepted=await q.CountAsync(o=>o.Channel!="InApp"&&o.SentAt!=null&&o.Status!="Pickup"),delivered=await q.CountAsync(o=>o.DeliveredAt!=null),read=await q.CountAsync(o=>o.ReadAt!=null),failed=await q.CountAsync(o=>new[]{"Failed","DeadLetter","Unknown","Unavailable","Bounced","Complaint"}.Contains(o.Status)),suppressed=await q.CountAsync(o=>o.Status=="Suppressed"),uniqueRecipients=await q.Select(o=>o.Recipient).Distinct().CountAsync(),channels=await q.GroupBy(o=>o.Channel).Select(g=>new{channel=g.Key,count=g.Count(),delivered=g.Count(o=>o.DeliveredAt!=null),readSupported=g.Key=="InApp"||g.Key=="WhatsApp",cost=attempts.Any(at=>g.Select(o=>o.Id).Contains(at.OutboxId)&&at.Cost!=null)?attempts.Where(at=>g.Select(o=>o.Id).Contains(at.OutboxId)&&at.Cost!=null).Sum(at=>at.Cost):(decimal?)null}).ToListAsync(),cost=await attempts.AnyAsync(at=>at.Cost!=null)?await attempts.SumAsync(at=>at.Cost):(decimal?)null,readMetric="Only authenticated in-app reads and verified provider read events; unsupported metrics are unavailable",teamOpen=await db.Set<Conversation>().CountAsync(c=>c.TenantId==tenant&&c.Kind=="Team"&&c.Status!="Resolved"&&(all&&workspace==null||c.UnitId!=null&&units.Contains(c.UnitId.Value)))});});
 t.MapGet("/notifications",async(Guid tenant,string? kind,bool? unread,AppDb db,Access a)=>{await a.Member(tenant);var q=db.Set<CommunicationNotification>().Where(n=>n.TenantId==tenant&&n.UserId==a.UserId);var count=await q.CountAsync(n=>n.ReadAt==null);if(kind!=null)q=q.Where(n=>n.Kind==kind);if(unread==true)q=q.Where(n=>n.ReadAt==null);return Results.Ok(new{unread=count,items=await q.OrderByDescending(n=>n.At).Take(100).Select(n=>new{n.Id,n.Title,n.Link,n.Kind,n.At,n.ReadAt}).ToListAsync()});});
 t.MapPost("/notifications/read",async(Guid tenant,AppDb db,Access a)=>{await a.Member(tenant);await db.Set<CommunicationNotification>().Where(n=>n.TenantId==tenant&&n.UserId==a.UserId&&n.ReadAt==null).ExecuteUpdateAsync(x=>x.SetProperty(n=>n.ReadAt,DateTimeOffset.UtcNow));return Results.NoContent();});
 t.MapPost("/notifications/{id:guid}/read",async(Guid tenant,Guid id,AppDb db,Access a)=>{await a.Member(tenant);var n=await db.Set<CommunicationNotification>().SingleOrDefaultAsync(n=>n.TenantId==tenant&&n.Id==id&&n.UserId==a.UserId)??throw new AccessDeniedException();n.ReadAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync();return Results.NoContent();});
 }
 static void ValidateAccount(AccountWrite r,CommunicationProviders providers){if(!new[]{"Email","SMS","WhatsApp"}.Contains(r.Channel)||!new[]{"Meta","Resend","Twilio","Gateway","Test"}.Contains(r.Provider)||r.Sender.Length>180||r.ProviderReference.Length>180||r.PerMinute is <1 or >1000||r.Provider=="Test"&&!providers.MockAllowed)throw new DomainException("Invalid or unavailable channel account");if(r.Provider=="Meta"&&r.Channel!="WhatsApp"||r.Provider=="Resend"&&r.Channel!="Email"||r.Provider=="Twilio"&&r.Channel!="SMS")throw new DomainException("Provider and channel do not match");if(r.Channel=="Email"&&!System.Net.Mail.MailAddress.TryCreate(r.Sender,out _))throw new DomainException("Enter a sender email address");if(r.Secrets!=null)MembershipService.Json(r.Secrets);}
 static void ApplyAccount(CommunicationAccount a,AccountWrite r,CommunicationProviders providers){if(a.Channel!=r.Channel||a.Sender!=r.Sender||a.Provider!=r.Provider||a.ProviderReference!=r.ProviderReference||r.Secrets!=null){a.Verified=false;a.Health="Verification required";}a.UnitId=r.UnitId;a.Name=r.Name;a.Channel=r.Channel;a.Provider=r.Provider;a.Sender=r.Sender;a.ProviderReference=r.ProviderReference;a.Enabled=r.Enabled;a.InboundEnabled=r.InboundEnabled;a.PerMinute=r.PerMinute;if(r.Secrets!=null)a.ProtectedSecrets=providers.Protect(r.Secrets);}
 static void MapAttachments(RouteGroupBuilder t){
 t.MapPost("/messages/{id:guid}/send",async(Guid tenant,Guid id,AppDb db,Access a,CommunicationService s)=>{var m=await db.Set<CommunicationMessage>().SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id&&m.SenderId==a.UserId)??throw new AccessDeniedException();var c=await s.Conversation(tenant,m.ConversationId,true);await a.Require(tenant,"communications.send",c.UnitId);var job=await db.Outbox.SingleOrDefaultAsync(o=>o.TenantId==tenant&&o.MessageId==id)??throw new DomainException("No pending delivery");if(job.Status=="Held"){job.Status="Queued";m.Status="Queued";await db.SaveChangesAsync();}return Results.Ok(new{m.Id,m.Status});});

 t.MapPost("/messages/{id:guid}/attachments",async(Guid tenant,Guid id,HttpRequest request,AppDb db,Access a,CommunicationService s,IObjectStore store)=>{var m=await db.Set<CommunicationMessage>().SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id&&m.SenderId==a.UserId&&m.RemovedAt==null)??throw new AccessDeniedException();var conversation=await s.Conversation(tenant,m.ConversationId,true);if(conversation.Channel!="InApp"&&!m.Internal&&(m.Status!="Draft"||conversation.Channel=="SMS"))throw new DomainException("External files require a held draft on a supported email or WhatsApp channel");if(request.ContentLength is null or >2097152||await db.Set<MessageAttachment>().CountAsync(f=>f.MessageId==id)>=5)throw new DomainException("Attach up to five files, each up to 2 MB");using var stream=new MemoryStream();await request.Body.CopyToAsync(stream);var bytes=stream.ToArray();var type=request.ContentType?.Split(';')[0]??"";if(type=="image/png")bytes=AssetEndpoints.SanitizePng(bytes);else if(type!="application/pdf"||bytes.Length<12||!Encoding.ASCII.GetString(bytes.Take(5).ToArray()).StartsWith("%PDF-")||!Encoding.ASCII.GetString(bytes.TakeLast(1024).ToArray()).Contains("%%EOF"))throw new DomainException("Use a sanitized PNG or PDF attachment");var name=Path.GetFileName(request.Headers["X-Filename"].ToString());if(name.Length>160)name=name[..160];var file=new MessageAttachment{TenantId=tenant,MessageId=id,Name=name,ContentType=type,Length=bytes.Length};await store.Put(tenant,file.Id,bytes);db.Add(file);a.Audit(tenant,"communication.attachment.created",file.Id);await db.SaveChangesAsync();return Results.Ok(new{file.Id,file.Name,file.ContentType});});
 t.MapGet("/attachments/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a,CommunicationService s,IObjectStore store)=>{var file=await db.Set<MessageAttachment>().SingleOrDefaultAsync(f=>f.Id==id&&f.TenantId==tenant)??throw new AccessDeniedException();var m=await db.Set<CommunicationMessage>().SingleOrDefaultAsync(m=>m.Id==file.MessageId&&m.TenantId==tenant&&m.RemovedAt==null)??throw new AccessDeniedException();var c=await s.Conversation(tenant,m.ConversationId);if(m.Status=="Draft"&&m.SenderId!=a.UserId||m.Internal&&(c.Kind!="Team"||!await a.Can(tenant,"communications.inbox",c.UnitId))||m.Status=="Pending Approval"&&m.SenderId!=a.UserId&&!await a.Can(tenant,"communications.approve",c.UnitId))throw new AccessDeniedException();return file.ContentType=="image/png"?Results.File(store.Open(tenant,id),file.ContentType):Results.File(store.Open(tenant,id),file.ContentType,Path.ChangeExtension(string.IsNullOrEmpty(file.Name)?"attachment":file.Name,".pdf"));});
 }
}
